self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    try {
      const cache = await caches.open(CACHE);
      for (const url of SHELL) {
        const res = await fetch(new Request(url, { cache: 'no-cache' }));
        /* a redirected response cannot be handed to a navigation, so one is as bad as a 404 */
        if (!res.ok || res.redirected) throw new Error('cannot precache ' + url + ' (' + res.status + ')');
        await cache.put(url, res);
      }
    } catch (err) {
      /* leave nothing, not a half-filled cache under the final name; failing the install keeps the
         previous worker (and its complete cache) in charge */
      console.warn('zoey-games: install failed, nothing kept - ' + err.message);
      await caches.delete(CACHE);
      throw err;
    }
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    for (const name of await caches.keys()) {
      /* an old shell, or an old voice - but a voice cache under the CURRENT name survives a new
         shell, which is the whole point of naming them separately */
      const mine = name.indexOf('zoey-games-') === 0 || name.indexOf('zoey-voice-') === 0;
      if (mine && name !== CACHE && name !== VCACHE) await caches.delete(name);
    }
    await self.clients.claim();
  })());
});

/* The voice fill. Never inside activate's waitUntil: fetch events are not dispatched to a worker
   that is still activating, so holding that promise open for 9.5 MB of audio would stall the very
   clips it is trying to keep. It runs on a message instead, inside THAT event's waitUntil, which
   is what keeps the worker alive while it works. */
let filling = null;
async function fillVoice() {
  const cache = await caches.open(VCACHE);
  const todo = [];
  for (const url of VOICE) if (!(await cache.match(url))) todo.push(url);
  let kept = 0, missing = 0, at = 0;
  /* four at a time: she is playing while this runs, and her next clip must not queue behind three
     hundred of them */
  const lane = async () => {
    while (at < todo.length) {
      const url = todo[at++];
      try {
        const res = await fetch(url, { cache: 'no-cache' });
        /* 200 only: Cache.put rejects a 206, and asking for no range should not get one */
        if (res.ok && res.status === 200 && !res.redirected) { await cache.put(url, res); kept++; }
        else missing++;
      } catch (e) { missing++; }
    }
  };
  await Promise.all([lane(), lane(), lane(), lane()]);
  return { kept: kept, missing: missing, total: VOICE.length, asked: todo.length };
}

self.addEventListener('message', (event) => {
  const d = event.data;
  if (!d || d.zoey !== 'fill-voice') return;
  if (!filling) {
    filling = fillVoice().then((r) => {
      filling = null;
      if (r.missing) console.warn('zoey-games: ' + r.missing + ' of ' + r.total + ' voice clips are not kept offline yet');
      return r;
    }, (e) => { filling = null; console.warn('zoey-games: keeping the voice offline failed - ' + e.message); });
  }
  event.waitUntil(filling);
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET' || new URL(req.url).origin !== self.location.origin) return;
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    /* the page itself: ./ and ./index.html are the same document, kept once, under ./ */
    const hit = await cache.match(req.mode === 'navigate' ? './' : req);
    if (hit) return hit;
    const heard = await (await caches.open(VCACHE)).match(req);
    if (heard) return heard;
    /* A miss goes to the network and is NOT stored here. An <audio> element asks with a Range
       header, the answer is a 206, and Cache.put rejects a 206 - so storing is the fill's job,
       which asks for the whole file and gets a 200. */
    return fetch(req);
  })());
});
